@import "@fontsource-variable/host-grotesk";
@import "@fontsource/dm-mono/400.css";

/* Light (faithful): white page, black ink, #888 secondary text. Orange #f60 for actions only.
   Pale band washes: faint bronze #f6f3ee, mint #ebfef6, lavender #f6f1fe with amethyst ink
   #5c2999. Dark bronze #665233 sub-lines on the bronze cards. */
:root {
  --background: #ffffff;
  --foreground: #000000;
  --card: #ffffff;
  --card-foreground: #000000;
  --popover: #ffffff;
  --popover-foreground: #000000;
  --primary: #ff6600;
  --primary-foreground: #ffffff;
  --secondary: #ebfef6;
  --secondary-foreground: #000000;
  --muted: #f6f3ee;
  --muted-foreground: #888888;
  --accent: #f6f1fe;
  --accent-foreground: #5c2999;
  --destructive: #d92d20;
  --destructive-foreground: #ffffff;
  --border: rgb(0 0 0 / 10%);
  --input: rgb(102 82 51 / 20%);
  --ring: #ff6600;
  --highlight: #665233;
  --highlight-foreground: #ffffff;
  --glow: #aa8855;
  --chart-1: #ff6600;
  --chart-2: #00cc88;
  --chart-3: #9944ff;
  --chart-4: #3f54bf;
  --chart-5: #00ccee;
  --sidebar: #f6f3ee;
  --sidebar-foreground: #000000;
  --sidebar-primary: #ff6600;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #ffffff;
  --sidebar-accent-foreground: #000000;
  --sidebar-border: rgb(0 0 0 / 10%);
  --sidebar-ring: #ff6600;

  --typeface-body: "Host Grotesk Variable", "Helvetica Neue", Arial, sans-serif;
  --typeface-display: "Host Grotesk Variable", "Helvetica Neue", Arial, sans-serif;
  --typeface-mono: "DM Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 1.5rem;
  /* 1184px of content inside the gutters, as the original's column */
  --page-width: 76.5rem;
  --page-gutter: 1.25rem;
  --section-y: 5rem;
}

/* Dark sibling: the original's black panels. Pure black page, glassy #1a1a1a cards
   (white at 10% on black), white ink, light-bronze #eec07a accent, the same orange. */
.dark {
  --background: #000000;
  --foreground: #ffffff;
  --card: #1a1a1a;
  --card-foreground: #ffffff;
  --popover: #1a1a1a;
  --popover-foreground: #ffffff;
  --primary: #ff6600;
  --primary-foreground: #ffffff;
  --secondary: #0b2219;
  --secondary-foreground: #ffffff;
  --muted: #1a1712;
  --muted-foreground: #8f8f8f;
  --accent: #1c1429;
  --accent-foreground: #c7a6ff;
  --destructive: #f0584c;
  --destructive-foreground: #ffffff;
  --border: rgb(255 255 255 / 10%);
  --input: rgb(255 255 255 / 16%);
  --ring: #ff6600;
  --highlight: #eec07a;
  --highlight-foreground: #261e12;
  --glow: #aa8855;
  --chart-1: #ff6600;
  --chart-2: #00cc88;
  --chart-3: #b27aff;
  --chart-4: #768cfa;
  --chart-5: #00ccee;
  --sidebar: #0d0d0d;
  --sidebar-foreground: #ffffff;
  --sidebar-primary: #ff6600;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #1a1a1a;
  --sidebar-accent-foreground: #ffffff;
  --sidebar-border: rgb(255 255 255 / 10%);
  --sidebar-ring: #ff6600;
}
